), inserted AS (
  INSERT INTO lands (owner_id, address, postal_code, area, lc_code, lc_code_nm, last_updt_dt,
    regstr_se_code_nm, cnrs_psn_co, pnu, ld_code_nm, region_sido, region_sigungu,
    region_eupmyeondong, desired_price, desired_area, description, status, transaction_type,
    x, y, prpos_area_code, prpos_area_name, prpos_area_cnflc_at, prpos_area_cnflc_at_nm,
    created_at, updated_at)
  SELECT (SELECT id FROM users WHERE email = 'dummy-land-owner@heilous.local' LIMIT 1),
    s.address, s.postal_code, s.area, s.lc_code, s.lc_code_nm, s.last_updt_dt,
    s.regstr_se_code_nm, s.cnrs_psn_co, s.pnu, s.ld_code_nm, s.region_sido, s.region_sigungu,
    s.region_eupmyeondong, s.desired_price, s.desired_area, s.description, s.status,
    s.transaction_type, s.x, s.y, s.prpos_area_code, s.prpos_area_name,
    s.prpos_area_cnflc_at, s.prpos_area_cnflc_at_nm, NOW(), NOW()
  FROM seed s
  RETURNING id
)
SELECT COUNT(*) AS inserted_rows FROM inserted;
COMMIT;
